#include "stdlib/lapack/base/dpbtf2.h"
#include "stdlib/lapack/base/shared.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define ITERATIONS 200
#define REPEATS 2

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Resets and factors a bounded band matrix, then reconstructs its input.
*
* @param N        matrix order
* @param upper    whether to store the upper triangle
* @param ndarray  whether to use signed column indexing
* @param failed   whether the first diagonal is zero
* @return         elapsed seconds or -1 on failure
*/
static double benchmark( const LAPACK_INT N, const int upper, const int ndarray, const int failed ) {
	double original[ 32 ] = { 0.0 };
	double AB[ 32 ];
	double diagonal;
	double previous;
	double coupling;
	double elapsed;
	double t;
	LAPACK_INT r;
	LAPACK_INT c;
	LAPACK_INT o;
	LAPACK_INT info;
	LAPACK_INT expected;
	LAPACK_INT star;
	LAPACK_INT i;
	LAPACK_INT j;
	int k;

	r = ndarray ? 1 : N;
	c = ndarray ? -2 : 1;
	o = ndarray ? 2*(N-1) : 0;
	for ( i = 0; i < 2*N; i++ ) {
		original[ i ] = 999.0;
	}
	for ( j = 0; j < N; j++ ) {
		original[ o+(upper ? r : 0)+(j*c) ] = ( failed && j == 0 ) ? 0.0 : (double)N+4.0;
		if ( upper && j > 0 ) {
			original[ o+(j*c) ] = 0.25;
		} else if ( !upper && j+1 < N ) {
			original[ o+r+(j*c) ] = 0.25;
		}
	}
	expected = failed ? 1 : 0;
	t = tic();
	for ( k = 0; k < ITERATIONS; k++ ) {
		// Include resetting the compact input in the measured workload:
		memcpy( AB, original, (size_t)(2*N)*sizeof( double ) );
		if ( ndarray ) {
			info = API_SUFFIX(c_dpbtf2_ndarray)( upper ? LAPACK_UPPER_TRIANGLE : LAPACK_LOWER_TRIANGLE, N, 1, AB, r, c, o );
		} else {
			info = API_SUFFIX(c_dpbtf2)( LAPACK_ROW_MAJOR, upper ? LAPACK_UPPER_TRIANGLE : LAPACK_LOWER_TRIANGLE, N, 1, AB, N );
		}
		if ( info != expected ) {
			return -1.0;
		}
	}
	elapsed = tic()-t;
	if ( failed ) {
		if ( memcmp( AB, original, (size_t)(2*N)*sizeof( double ) ) != 0 ) {
			return -1.0;
		}
	} else {
		previous = 0.0;
		for ( j = 0; j < N; j++ ) {
			diagonal = AB[ o+(upper ? r : 0)+(j*c) ];
			coupling = 0.0;
			if ( j > 0 ) {
				coupling = upper ? AB[ o+(j*c) ] : AB[ o+r+((j-1)*c) ];
				if ( fabs( previous*coupling-0.25 ) > 1.0e-12 ) {
					return -1.0;
				}
			}
			if ( !isfinite( diagonal ) || !isfinite( coupling ) || diagonal <= 0.0 || fabs( diagonal*diagonal+coupling*coupling-((double)N+4.0) ) > 1.0e-11 ) {
				return -1.0;
			}
			previous = diagonal;
		}
	}
	star = upper ? o : o+r+((N-1)*c);
	if ( AB[ star ] != 999.0 ) {
		return -1.0;
	}
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	const LAPACK_INT sizes[] = { 8, 16 };
	double elapsed;
	int count;
	int passing;
	int i;
	int upper;
	int ndarray;
	int failed;
	int repeat;

	count = 0;
	passing = 0;
	printf( "TAP version 13\n" );
	for ( i = 0; i < 2; i++ ) {
		for ( upper = 0; upper < 2; upper++ ) {
			for ( ndarray = 0; ndarray < 2; ndarray++ ) {
				for ( failed = 0; failed < 2; failed++ ) {
					for ( repeat = 0; repeat < REPEATS; repeat++ ) {
						count += 1;
						printf( "# c::dpbtf2:N=%d:upper=%d:ndarray=%d:failed=%d\n", (int)sizes[ i ], upper, ndarray, failed );
						elapsed = benchmark( sizes[ i ], upper, ndarray, failed );
						if ( elapsed < 0.0 ) {
							printf( "not ok %d benchmark failed\n", count );
						} else {
							printf( "ok %d benchmark finished; %d iterations; %.9f seconds\n", count, ITERATIONS, elapsed );
							passing += 1;
						}
					}
				}
			}
		}
	}
	printf( "1..%d\n# total %d\n# pass  %d\n", count, count, passing );
	return ( passing == count ) ? EXIT_SUCCESS : EXIT_FAILURE;
}
